    try{ require("fs").appendFileSync(require("path").join(require("os").homedir(), ".openclaw", "logs", "xuanshu-probe.log"), "[" + new Date().toISOString() + "] AFTER-SETUP+ENSURE-INVOKED\r\n", "utf8"); }catch(e4){}
    // 启动后多次固化配置，对冲 gateway 内置模板写回厂家默认
